public class TimeExample {
    public void processEvents() {
        LocalDate today = LocalDate.now();
        LocalTime shiftStart = LocalTime.of(9, 0);
        LocalDateTime appointment = LocalDateTime.of(today, shiftStart);

        // Immutability: appointment remains unchanged
        LocalDateTime nextWeek = appointment.plusWeeks(1);

        System.out.println("Next appointment: " + nextWeek.format(DateTimeFormatter.ISO_LOCAL_DATE_TIME));
    }
}
